import{_ as t,o as e,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-11（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-11.md","filePath":"topics/biomedicine/science-daily-2026-10-11.md"}'),i={name:"topics/biomedicine/science-daily-2026-10-11.md"};function r(c,o,a,l,g,d){return e(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-11-生物医学" tabindex="-1">科学日报 · 2026-10-11（生物医学） <a class="header-anchor" href="#科学日报-·-2026-10-11-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-10-11（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-11.md</code> — 第34期</p></blockquote><hr><h2 id="羽扇豆有毒生物碱的完整合成通路被解析-science" tabindex="-1">羽扇豆有毒生物碱的完整合成通路被解析（Science） <a class="header-anchor" href="#羽扇豆有毒生物碱的完整合成通路被解析-science" aria-label="Permalink to &quot;羽扇豆有毒生物碱的完整合成通路被解析（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-11.md</code> ｜ DOI: 10.1126/science.aei5520</p></blockquote><ul><li>对象：<strong>羽扇豆（Lupinus）</strong>——很有前景的蛋白作物，却积累<strong>苦涩且有毒的喹诺里西啶生物碱（QA）</strong>，限制其食用/饲用；用育种去毒长期受困于对 QA <strong>生物合成</strong>的不了解。</li><li>方法：<strong>通路重构 + 突变体分析</strong>，在**窄叶羽扇豆（L. angustifolius）**中解析出完整 QA 通路——<strong>共 15 个酶促步骤</strong>。</li><li>机制亮点：<strong>类主要乳胶蛋白（major latex protein-like）</strong> 通过<strong>加速自发的化学平衡</strong>来推动反应（不是直接催化）；一个<strong>类氧化还原酶蛋白</strong>负责<strong>立体选择性</strong>。</li><li>结果：构建出一株<strong>新的低生物碱 NLL 品系</strong>，并在已有的<strong>低生物碱白羽扇豆（L. albus）<strong>品系中定位到</strong>致因突变</strong>。</li><li>意义：把&quot;<strong>有毒 QA 的遗传+生化基础</strong>&quot;讲清，为**野生羽扇豆及其他含 QA 豆科的&quot;从头驯化&quot;**扫清关键障碍。</li></ul><h2 id="表观遗传衰老越快、转座子越乱-狗狗体型与寿命的分子线索-science" tabindex="-1">表观遗传衰老越快、转座子越乱：狗狗体型与寿命的分子线索（Science） <a class="header-anchor" href="#表观遗传衰老越快、转座子越乱-狗狗体型与寿命的分子线索-science" aria-label="Permalink to &quot;表观遗传衰老越快、转座子越乱：狗狗体型与寿命的分子线索（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-11.md</code> ｜ DOI: 10.1126/science.aeb2986</p></blockquote><ul><li>对象：<strong>家犬</strong>——体型差异极大、寿命天差地别，是检验&quot;<strong>内在衰老速率如何塑造寿命</strong>&quot;的天然实验。</li><li>方法：<strong>894 只狗的 1640 份甲基化组</strong> → 建立<strong>表观遗传时钟</strong>，能预测死亡风险，并发现<strong>表观遗传衰老在生命早期最快</strong>。</li><li>守恒性：在<strong>人类年龄相关基因的同源位点</strong>上，狗的启动子甲基化随年龄的变化与人类<strong>一致</strong>，提示<strong>免疫通路重塑</strong>保守。</li><li>核心发现：<strong>体型更大、寿命更短的狗（以及雄性）<strong>表现出</strong>更快的分子衰老</strong>；两种效应机制不同——<strong>性别相关</strong>甲基化集中在 <strong>X 染色体</strong>，<strong>体型相关</strong>甲基化特别富集在<strong>转座元件（TE）</strong> 上。</li><li>意义：把&quot;<strong>体型压缩寿命</strong>&quot;的潜在中介指向 <strong>TE（转座子失调）</strong>，为衰老研究给出可检验的分子候选。</li><li>洞察：本库反复出现的母题——<strong>&quot;表型差异（大狗命短）&quot;落到分子层，不是一个开关，而是至少两条正交通道（性别轴 / 体型轴）</strong>。与 <code>science-daily-2026-10-10.md</code>（ZFP423 减脂拆成&quot;摄入轴 × 消耗轴&quot;）同构：<strong>看任何&quot;单一原因&quot;的寿命/代谢差异，先问它拆成几条独立轴、各自在哪个分子层面。</strong> 与 <code>home-fat-burning.md</code>（静息代谢/产热）在&quot;<strong>衰老速率可被测量、且与能量代谢纠缠</strong>&quot;上呼应。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第34期 科学板块</p></blockquote><p>关键词：羽扇豆、喹诺里西啶生物碱、QA、15 步通路、类主要乳胶蛋白、立体选择性、去毒驯化、窄叶羽扇豆；家犬、表观遗传时钟、甲基化组、生命早期衰老最快、转座元件 TE、X 染色体、体型-寿命、免疫通路重塑 关联：<code>topics/biomedicine/science-daily-2026-10-10.md</code>（前一日：PI(3,4)P₂ 线粒体融合、LPS 转运、ZFP423 产热疗法）、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>（生物医学主线）、<code>topics/biomedicine/chloroplast-endosymbiosis.md</code>（细胞器被驯化的分子层同源母题）、<code>topics/fitness/home-fat-burning.md</code>（衰老速率与能量代谢的健身侧对读）</p>',12)])])}const p=t(i,[["render",r]]);export{m as __pageData,p as default};
